@app.post("/api/checkout")
@login_required
def checkout():
    data = request.get_json()
    total = data["total"]                       # precio decidido por el cliente
    code = data.get("promo")
    if code and Promo.query.filter_by(code=code).first():
        total = total * 0.5                     # intentos ilimitados, reutilización ilimitada
    return charge(current_user, total)

