@app.post("/api/checkout")
@login_required
@rate_limit("10/minute", key=lambda: current_user.id)
def checkout():
    cart = Cart.for_user(current_user)           # fuente de verdad en el servidor
    total = cart.total()                         # los precios vienen del catálogo
    code = request.get_json().get("promo")
    if code:
        promo = Promo.redeem(code, user=current_user)   # un solo uso por usuario, atómico
        if promo is None:
            abort(400, "invalid promo")
        total = promo.apply(total)
    return charge(current_user, total)

