def test_client_cannot_choose_the_price(client, alice, cart_of_100):
    r = client.post("/api/checkout", json={"total": 1}, auth=alice)
    assert charged_amount(r) == 100

def test_promo_is_single_use(client, alice, promo_half_off):
    assert client.post("/api/checkout", json={"promo": promo_half_off}, auth=alice).status_code == 200
    assert client.post("/api/checkout", json={"promo": promo_half_off}, auth=alice).status_code == 400

def test_promo_guessing_is_throttled(client, alice):
    codes = [client.post("/api/checkout", json={"promo": f"TRY{i}"}, auth=alice).status_code for i in range(30)]
    assert 429 in codes
